17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.ArrayList;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.regex.Pattern;
25	
26	import org.slf4j.Logger;
27	import org.slf4j.LoggerFactory;
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
32	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
33	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
34	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
35	import org.springframework.samples.petclinic.rest.advice.OwnerCityFullException;
36	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitException;
37	import org.springframework.samples.petclinic.mapper.OwnerMapper;
38	import org.springframework.samples.petclinic.mapper.PetMapper;
39	import org.springframework.samples.petclinic.mapper.VisitMapper;
40	import org.springframework.samples.petclinic.model.Owner;
41	import org.springframework.samples.petclinic.model.Pet;
42	import org.springframework.samples.petclinic.model.Visit;
43	import org.springframework.samples.petclinic.rest.api.OwnersApi;
44	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
45	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
46	import org.springframework.samples.petclinic.rest.dto.PetDto;
47	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
48	import org.springframework.samples.petclinic.rest.dto.VisitDto;
49	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.security.access.prepost.PreAuthorize;
52	import org.springframework.util.StringUtils;
53	import org.springframework.web.bind.annotation.CrossOrigin;
54	import org.springframework.web.bind.annotation.RequestMapping;
55	import org.springframework.web.bind.annotation.RestController;
56	import org.springframework.web.util.UriComponentsBuilder;
57	
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    /**
70	     * Basic syntactic check for an email address: a non-empty local part, an '@', and a domain with
71	     * at least one dot and a two-or-more letter top-level label. Case is ignored here; accepted
72	     * addresses are lower-cased before being stored.
73	     */
74	    private static final Pattern EMAIL_PATTERN =
75	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
76	
77	    /**
78	     * Dedicated logger for audit side-effects. Emitting audit records on a well-known, separately
79	     * named logger keeps them addressable independently of the class's diagnostic logging.
80	     */
81	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
82	
83	    /**
84	     * Maximum number of owners a single city may contain. A create that would take the owner's city
85	     * to more than this many owners - i.e. the city already holds this many - is rejected with a 409.
86	     */
87	    private static final int CITY_OWNER_LIMIT = 50;
88	
89	    /**
90	     * Maximum number of owners that may be registered on a single day. A create that would take the
91	     * number of owners sharing a {@code registrationDate} beyond this many - i.e. that many owners
92	     * have already been created that day - is rejected with a 429.
93	     */
94	    private static final int DAILY_OWNER_LIMIT = 100;
95	
96	    /**
97	     * Number of owners that must already have been created for a given day before the create
98	     * response flags a bulk sign-up. When more than this many owners already share a
99	     * {@code registrationDate}, the response's {@code bulkSignupWarning} is {@code true}.
100	     */
101	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
102	
103	    private final ClinicService clinicService;
104	
105	    private final OwnerMapper ownerMapper;
106	
107	    private final PetMapper petMapper;
108	
109	    private final VisitMapper visitMapper;
110	
111	    public OwnerRestControllerV1(ClinicService clinicService,
112	                                 OwnerMapper ownerMapper,
113	                                 PetMapper petMapper,
114	                                 VisitMapper visitMapper) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	    }
120	
121	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
122	    @Override
123	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
124	        Collection<Owner> owners;
125	        if (lastName != null) {
126	            owners = this.clinicService.findOwnerByLastName(lastName);
127	        } else {
128	            owners = this.clinicService.findAllOwners();
129	        }
130	        if (owners.isEmpty()) {
131	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
132	        }
133	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Override
138	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
139	        Owner owner = this.clinicService.findOwnerById(ownerId);
140	        if (owner == null) {
141	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
142	        }
143	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
144	        ownerDto.setBulkSignupWarning(isBulkSignupDay(owner.getRegistrationDate()));
145	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
146	    }
147	
148	    /**
149	     * Determines whether the supplied day currently holds more than {@link #BULK_SIGNUP_WARNING_THRESHOLD}
150	     * owners sharing that {@code registrationDate}, which flags an unusually high volume of same-day
151	     * owner sign-ups.
152	     *
153	     * @param registrationDate the day to inspect, or {@code null}
154	     * @return {@code true} when more than the threshold of owners are registered on that day
155	     */
156	    private boolean isBulkSignupDay(LocalDate registrationDate) {
157	        return registrationDate != null
158	            && countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD;
159	    }
160	
161	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
162	    @Override
163	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
164	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
165	        validateRequiredFields(ownerFieldsDto);
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
169	        owner.setEmail(normalizeEmail(owner.getEmail()));
170	        if (owner.getRegistrationDate() == null) {
171	            owner.setRegistrationDate(LocalDate.now());
172	        }
173	        owner.setRegistrationDate(toBusinessDay(owner.getRegistrationDate()));
174	        if (!this.clinicService.findOwnerByTelephone(owner.getTelephone()).isEmpty()) {
175	            throw new DuplicateOwnerTelephoneException(owner.getTelephone());
176	        }
177	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())
178	            && isDuplicateHousehold(owner.getLastName(), owner.getAddress())) {
179	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
180	        }
181	        if (countOwnersInCity(owner.getCity()) >= CITY_OWNER_LIMIT) {
182	            throw new OwnerCityFullException(owner.getCity());
183	        }
184	        long ownersRegisteredOnDay = countOwnersRegisteredOn(owner.getRegistrationDate());
185	        if (ownersRegisteredOnDay >= DAILY_OWNER_LIMIT) {
186	            throw new OwnerDailyLimitException(owner.getRegistrationDate());
187	        }
188	        boolean bulkSignupWarning = ownersRegisteredOnDay > BULK_SIGNUP_WARNING_THRESHOLD;
189	        owner.setCustomerCode(buildCustomerCode(owner.getCity(), owner.getLastName()));
190	        owner.setHouseholdId(HouseholdNormalizer.householdId(owner.getLastName(), owner.getAddress()));
191	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
192	        this.clinicService.saveOwner(owner);
193	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
194	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
195	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
196	        ownerDto.setBulkSignupWarning(bulkSignupWarning);
197	        headers.setLocation(UriComponentsBuilder.newInstance()
198	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
199	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
200	    }
201	
202	    /**
203	     * Rejects an owner payload that is missing or blank in any required field. Collects the name of
204	     * every offending field and, if there is at least one, raises a {@link MissingOwnerFieldsException}
205	     * so the client receives a 400 whose {@code errors} array lists each missing field. The address is
206	     * checked in its {@link AddressNormalizer#normalize normalized} form, so a value that is blank only
207	     * after normalization is still rejected.
208	     *
209	     * @param ownerFieldsDto the submitted owner fields
210	     */
211	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
212	        List<String> missingFields = new ArrayList<>();
213	        if (!StringUtils.hasText(ownerFieldsDto.getFirstName())) {
214	            missingFields.add("firstName");
215	        }
216	        if (!StringUtils.hasText(ownerFieldsDto.getLastName())) {
217	            missingFields.add("lastName");
218	        }
219	        if (!StringUtils.hasText(ownerFieldsDto.getAddress())) {
220	            missingFields.add("address");
221	        }
222	        if (!StringUtils.hasText(ownerFieldsDto.getCity())) {
223	            missingFields.add("city");
224	        }
225	        if (!StringUtils.hasText(ownerFieldsDto.getTelephone())) {
226	            missingFields.add("telephone");
227	        }
228	        if (!missingFields.isEmpty()) {
229	            throw new MissingOwnerFieldsException(missingFields);
230	        }
231	    }
232	
233	    /**
234	     * Normalizes an optional email address for owner creation. Email is optional, so a missing or
235	     * blank value is left untouched. When a value is supplied it must be a syntactically valid
236	     * address; the accepted value is lower-cased before it is stored and returned.
237	     *
238	     * @param email the raw email value submitted by the client, or {@code null}
239	     * @return the lower-cased email, or the original blank/{@code null} value when none was supplied
240	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
241	     */
242	    private String normalizeEmail(String email) {
243	        if (!StringUtils.hasText(email)) {
244	            return email;
245	        }
246	        if (!EMAIL_PATTERN.matcher(email).matches()) {
247	            throw new InvalidOwnerFieldsException(List.of("email"));
248	        }
249	        return email.toLowerCase();
250	    }
251	
252	    /**
253	     * Builds the owner's customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where CITY3 is the
254	     * upper-cased first three letters of the city, LAST3 is the upper-cased first three letters of the
255	     * last name and NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
256	     * of owners already in that city (e.g. {@code SYD-SMI-0007}).
257	     *
258	     * @param city the owner's city
259	     * @param lastName the owner's last name
260	     * @return the assigned customer code
261	     */
262	    private String buildCustomerCode(String city, String lastName) {
263	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
264	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
265	        int sequence = (int) this.clinicService.findAllOwners().stream()
266	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
267	            .count() + 1;
268	        return String.format("%s-%s-%04d", city3, last3, sequence);
269	    }
270	
271	    /**
272	     * Determines whether an existing owner already shares a household with the supplied last name and
273	     * address. Two owners belong to the same household when {@link HouseholdNormalizer#sameHousehold}
274	     * considers their last name and address a match.
275	     *
276	     * @param lastName the submitted owner's last name
277	     * @param address the submitted owner's address
278	     * @return {@code true} if another owner already has the same normalized last name and address
279	     */
280	    /**
281	     * Counts how many owners already exist that share the supplied first and last name, compared
282	     * case-insensitively. This reflects the number of namesakes present <em>before</em> the current
283	     * owner is created and is stored on the new owner as its {@code namesakeCount}.
284	     *
285	     * @param firstName the submitted owner's first name
286	     * @param lastName the submitted owner's last name
287	     * @return the number of existing owners with the same first and last name, ignoring case
288	     */
289	    private int countNamesakes(String firstName, String lastName) {
290	        return (int) this.clinicService.findAllOwners().stream()
291	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
292	                && lastName.equalsIgnoreCase(existing.getLastName()))
293	            .count();
294	    }
295	
296	    private boolean isDuplicateHousehold(String lastName, String address) {
297	        return this.clinicService.findAllOwners().stream()
298	            .anyMatch(existing -> HouseholdNormalizer.sameHousehold(
299	                lastName, address, existing.getLastName(), existing.getAddress()));
300	    }
301	
302	    /**
303	     * Counts how many owners already live in the supplied city, compared case-insensitively. Used to
304	     * enforce the per-city capacity limit when a new owner is created.
305	     *
306	     * @param city the submitted owner's city
307	     * @return the number of existing owners in that city, ignoring case
308	     */
309	    private long countOwnersInCity(String city) {
310	        return this.clinicService.findAllOwners().stream()
311	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
312	            .count();
313	    }
314	
315	    /**
316	     * Counts how many owners have already been created on the supplied registration date. Used to
317	     * enforce the per-day capacity limit when a new owner is created.
318	     *
319	     * @param registrationDate the registration date of the owner being created
320	     * @return the number of existing owners already registered on that date
321	     */
322	    /**
323	     * Rolls a registration date forward to a business day. A registration date must fall on a
324	     * business day, so when the supplied or defaulted date lands on a Saturday or Sunday it is
325	     * moved forward to the following Monday; a weekday is returned unchanged. Every value derived
326	     * from the registration date (such as the membership number's year segment) and the daily
327	     * create-limit therefore use the adjusted date.
328	     *
329	     * @param date the effective registration date, whether supplied or defaulted to the server date
330	     * @return the same date when it is a weekday, otherwise the next Monday
331	     */
332	    private LocalDate toBusinessDay(LocalDate date) {
333	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
334	            date = date.plusDays(1);
335	        }
336	        return date;
337	    }
338	
339	    private long countOwnersRegisteredOn(LocalDate registrationDate) {
340	        return this.clinicService.findAllOwners().stream()
341	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
342	            .count();
343	    }
344	
345	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
346	    @Override
347	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
348	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
349	        if (currentOwner == null) {
350	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
351	        }
352	        currentOwner.setAddress(ownerFieldsDto.getAddress());
353	        currentOwner.setCity(ownerFieldsDto.getCity());
354	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
355	        currentOwner.setLastName(ownerFieldsDto.getLastName());
356	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
357	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
358	        this.clinicService.saveOwner(currentOwner);
359	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
360	    }
361	
362	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
363	    @Transactional
364	    @Override
365	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
366	        Owner owner = this.clinicService.findOwnerById(ownerId);
367	        if (owner == null) {
368	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
369	        }
370	        this.clinicService.deleteOwner(owner);
371	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
372	    }
373	
374	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
375	    @Override
376	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
377	        Owner owner = this.clinicService.findOwnerById(ownerId);
378	        if (owner == null) {
379	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
380	        }
381	        HttpHeaders headers = new HttpHeaders();
382	        Pet pet = petMapper.toPet(petFieldsDto);
383	        owner.setId(ownerId);
384	        pet.setOwner(owner);
385	        pet.getType().setName(null);
386	        this.clinicService.savePet(pet);
387	        PetDto petDto = petMapper.toPetDto(pet);
388	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
389	            .buildAndExpand(pet.getId()).toUri());
390	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
391	    }
392	
393	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
394	    @Override
395	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
396	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
397	        if (currentOwner != null) {
398	            Pet currentPet = this.clinicService.findPetById(petId);
399	            if (currentPet != null) {
400	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
401	                currentPet.setName(petFieldsDto.getName());
402	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
403	                this.clinicService.savePet(currentPet);
404	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
405	            }
406	        }
407	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
408	    }
409	
410	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
411	    @Override
412	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
413	        HttpHeaders headers = new HttpHeaders();
414	        Visit visit = visitMapper.toVisit(visitFieldsDto);
415	        Pet pet = new Pet();
416	        pet.setId(petId);
417	        visit.setPet(pet);
418	        this.clinicService.saveVisit(visit);
419	        VisitDto visitDto = visitMapper.toVisitDto(visit);
420	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
421	            .buildAndExpand(visit.getId()).toUri());
422	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
423	    }
424	
425	
426	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
427	    @Override
428	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
429	        Owner owner = this.clinicService.findOwnerById(ownerId);
430	        if (owner != null) {
431	            Pet pet = owner.getPet(petId);
432	            if (pet != null) {
433	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
434	            }
435	        }
436	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
437	    }
438	}
